// The resin visualization contract, typed structurally.
//
// These interfaces mirror `RunResult.viz` of @nullarch/resin (0.2.0). They are
// deliberately structural rather than imported: the adapter consumes the data
// shape — a plain JSON object, whether it came from `run(result, data).viz` or
// from `resin run --viz out.json` — and must not force a dependency on the
// compiler package. tests/gen-fixtures.mjs regenerates fixtures from the real
// resin, which is what keeps this mirror honest.

export interface ResinBars {
  open: ArrayLike<number>;
  high: ArrayLike<number>;
  low: ArrayLike<number>;
  close: ArrayLike<number>;
  volume?: ArrayLike<number>;
  /** UNIX milliseconds per bar, as resin's OHLCVData carries them. */
  time?: ArrayLike<number>;
}

export interface ResinVizPlot {
  title: string;
  style: string; // line | stepline | stepline_diamond | histogram | area | areabr | columns | cross | circles | linebr
  linewidth: number;
  offset: number;
  histbase: number;
  trackprice: boolean;
  forceOverlay: boolean;
  color: string | null;
  colors: (string | null)[] | null;
  /** The value series (na is NaN in-process, null after a JSON round-trip). */
  values: (number | null)[];
}

export interface ResinVizShape {
  title: string | null;
  style: string; // shape.* name without the prefix
  location: string; // abovebar | belowbar | top | bottom | absolute
  size: string; // auto | tiny | small | normal | large | huge
  text: string | null;
  textcolor: string | null;
  offset: number;
  forceOverlay: boolean;
  color: string | null;
  colors: (string | null)[] | null;
  condition: boolean[];
}

export interface ResinVizChar extends Omit<ResinVizShape, "style"> {
  char: string;
}

export interface ResinVizArrow {
  title: string | null;
  colorup: string | null;
  colordown: string | null;
  minheight: number;
  maxheight: number;
  offset: number;
  forceOverlay: boolean;
  values: (number | null)[]; // NaN arrives as null when parsed from JSON
}

export interface ResinVizCandle {
  title: string | null;
  color: string | null;
  colors: (string | null)[] | null;
  wickcolor: string | null;
  bordercolor: string | null;
  forceOverlay: boolean;
  open: (number | null)[];
  high: (number | null)[];
  low: (number | null)[];
  close: (number | null)[];
}

export interface ResinVizBgcolor {
  title: string | null;
  offset: number;
  forceOverlay: boolean;
  color: string | null;
  colors: (string | null)[] | null;
}

export interface ResinVizBarcolor {
  title: string | null;
  offset: number;
  color: string | null;
  colors: (string | null)[] | null;
}

export interface ResinVizHline {
  title: string | null;
  price: number | null;
  color: string | null;
  linestyle: string; // solid | dotted | dashed
  linewidth: number;
}

export interface ResinVizFill {
  a: { kind: "plot" | "hline"; index: number } | null;
  b: { kind: "plot" | "hline"; index: number } | null;
  title: string | null;
  color: string | null;
  colors: (string | null)[] | null;
}

export interface ResinVizDrawing {
  kind: string; // label | line | box | table
  id: number;
  bar: number;
  state: Record<string, number | string | null>;
}

export interface ResinViz {
  overlay: boolean;
  plots: ResinVizPlot[];
  bgcolors: ResinVizBgcolor[];
  barcolors: ResinVizBarcolor[];
  hlines: ResinVizHline[];
  fills: ResinVizFill[];
  shapes: ResinVizShape[];
  chars: ResinVizChar[];
  arrows: ResinVizArrow[];
  candles: ResinVizCandle[];
  plotbars: ResinVizCandle[];
}

/** Anything with a `viz` — lets callers pass a whole RunResult straight in. */
export interface HasViz {
  viz?: ResinViz;
}
